        self._dtype = _TORCH_DTYPES_MAPPING[int(data_format.split(":")[1])]

    def deserialize(self, data: bytes) -> torch.Tensor:
        dtype_indice = self._dtype_to_indices[self._dtype]
        tensor_bytes = np.frombuffer(data, dtype=np.uint8)
        tensor = torch.from_numpy(tensor_bytes.reshape(self._get_shape(tensor_bytes)))
        return tensor.to(self._dtype)

    def _get_shape(self, tensor_bytes: np.ndarray) -> Tuple[int, ...]:
        num_dims = np.frombuffer(tensor_bytes[0:4], dtype=np.uint32).item()
        shape = []
        for dim_idx in range(num_dims):
            shape.append(np.frombuffer(tensor_bytes[4 + 4 * dim_idx : 4 + 4 * (dim_idx + 1)], dtype=np.uint32).item())
        return tuple(shape)
